@jkotas When I use following code:

```cs
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;

namespace InliningExperiment
{
    internal class Program
    {
        static int Main() => FirstLevel("Hello, World!", 'a');

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int FirstLevel<T>(ReadOnlySpan<T> span, T value) where T : IEquatable<T>?
            => SecondLevel(ref MemoryMarshal.GetReference(span), value, span.Length);

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int SecondLevel<T>(ref T searchSpace, T value, int length) where T : IEquatable<T>?
        {
            if (typeof(T) == typeof(char))
            {
                return ThirdLevel(ref searchSpace, value, length);
            }

            return 0;
        }

        private static int ThirdLevel<T>(ref T searchSpace, T value, int length) where T : IEquatable<T>?
            => throw new Exception($"Length was {length}");
    }
}
```

